import { expect, expectStatus, test, uniqueName, type APIRequestContext } from "../../fixtures";

const KINDS = ["w9", "insurance_certificate", "contract"] as const;

async function uploadAll(member: APIRequestContext, vendorId: string) {
  const documentIds: Record<string, string> = {};
  for (const kind of KINDS) {
    const response = await member.post(`/api/vendors/${vendorId}/documents`, {
      multipart: {
        kind,
        file: { name: `${kind}.pdf`, mimeType: "application/pdf", buffer: Buffer.from("%PDF-1.4 test") },
      },
    });
    const doc = await expectStatus<{ id: string }>(response, 201);
    documentIds[kind] = doc.id;
  }
  return documentIds;
}

test.describe("vendor lifecycle", () => {
  test(
    "rejecting one document sends the whole vendor back",
    { tag: "@LIF-02" },
    async ({ apiAs }) => {
      // Arrange: a vendor in review with three pending extractions
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");

      const created = await expectStatus<{ id: string }>(
        await member.post("/api/vendors", {
          data: {
            name: uniqueName("Lifecycle Reject"),
            category: "services",
            contact_email: `${uniqueName("ap").toLowerCase().replace(/[^a-z0-9]/g, "")}@example.test`,
          },
        }),
        201,
      );
      const vendorId = created.id;

      const documentIds = await uploadAll(member, vendorId);

      // Wait until every document has been extracted.
      for (const documentId of Object.values(documentIds)) {
        await expect
          .poll(
            async () => {
              const doc = await expectStatus<{ status: string }>(
                await member.get(`/api/documents/${documentId}`),
                200,
              );
              return doc.status;
            },
            { timeout: 60_000 },
          )
          .toBe("extracted");
      }

      await expectStatus(await member.post(`/api/vendors/${vendorId}/submit`), 200);

      // Find the contract extraction and confirm the three extractions are pending.
      const pending: Record<string, { id: string; status: string }> = {};
      for (const [kind, documentId] of Object.entries(documentIds)) {
        const extraction = await expectStatus<{ id: string; status: string }>(
          await member.get(`/api/documents/${documentId}/extraction`),
          200,
        );
        pending[kind] = extraction;
      }
      for (const kind of KINDS) {
        expect(pending[kind].status).toBe("pending_review");
      }

      // Act: reviewer rejects the contract extraction
      const decided = await expectStatus<{ status: string; review_note: string | null }>(
        await reviewer.post(`/api/extractions/${pending.contract.id}/decision`, {
          data: { decision: "reject", note: "Wrong counterparty" },
        }),
        200,
      );

      // Assert: extraction rejected with the note
      expect(decided.status).toBe("rejected");
      expect(decided.review_note).toBe("Wrong counterparty");

      // Assert: vendor status is rejected
      const vendor = await expectStatus<{ status: string }>(
        await member.get(`/api/vendors/${vendorId}`),
        200,
      );
      expect(vendor.status).toBe("rejected");

      // Assert: audit events recorded in order, extraction.rejected before vendor.rejected
      const trail = await expectStatus<{ items: { action: string }[] }>(
        await member.get(`/api/vendors/${vendorId}/audit`),
        200,
      );
      const actions = trail.items.map((e) => e.action);
      const extractionIdx = actions.indexOf("extraction.rejected");
      const vendorIdx = actions.indexOf("vendor.rejected");
      expect(extractionIdx).toBeGreaterThanOrEqual(0);
      expect(vendorIdx).toBeGreaterThanOrEqual(0);
      expect(extractionIdx).toBeLessThan(vendorIdx);
    },
  );
});
